static bool is_bfin_call(unsigned short *addr)
{
	unsigned int opcode;

	if (!get_instruction(&opcode, addr))
		return false;

	if ((opcode >= 0x0060 && opcode <= 0x0067) ||
	    (opcode >= 0x0070 && opcode <= 0x0077) ||
	    (opcode >= 0xE3000000 && opcode <= 0xE3FFFFFF))
		return true;

	return false;

}

